import{_ as o,a as s,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · 全册短语与句型 · 第1–23课","description":"按课次汇总短语用法与原创句型，链接对应课时。","frontmatter":{"title":"第三册：培养技能 · 全册短语与句型 · 第1–23课","description":"按课次汇总短语用法与原创句型，链接对应课时。","splitFrom":"life/english/new-concept/book-3/phrases.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第三册：培养技能 · 全册短语与句型","summary":"按课次汇总短语用法与原创句型，链接对应课时。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 全册短语与句型","link":"/life/english/new-concept/book-3/phrases"},"next":{"text":"第三册：培养技能 · 全册短语与句型 · 第24–48课","link":"/life/english/new-concept/book-3/phrases-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 全册短语与句型","link":"/life/english/new-concept/book-3/phrases"},"next":{"text":"第三册：培养技能 · 全册短语与句型 · 第24–48课","link":"/life/english/new-concept/book-3/phrases-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-3/phrases-part-01.md","filePath":"life/english/new-concept/book-3/phrases-part-01.md"}'),l={name:"life/english/new-concept/book-3/phrases-part-01.md"};function t(i,e,r,h,p,c){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-全册短语与句型-·-第1–23课" tabindex="-1">第三册：培养技能 · 全册短语与句型 · 第1–23课 <a class="header-anchor" href="#第三册-培养技能-·-全册短语与句型-·-第1–23课" aria-label="Permalink to &quot;第三册：培养技能 · 全册短语与句型 · 第1–23课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/phrases">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-3/overview">本册介绍</a> · <a href="/life/english/new-concept/book-3/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-3/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-3/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-3/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-3/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-3/review">综合复习与自测</a></p><h2 id="第三册-培养技能-·-全册短语与句型" tabindex="-1">第三册：培养技能 · 全册短语与句型 <a class="header-anchor" href="#第三册-培养技能-·-全册短语与句型" aria-label="Permalink to &quot;第三册：培养技能 · 全册短语与句型 {#第三册-培养技能-·-全册短语与句型}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-3/overview">本册介绍</a> · <a href="/life/english/new-concept/book-3/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-3/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-3/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-3/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-3/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-3/review">综合复习与自测</a></p><h2 id="lesson-1-·-定语从句与证据限定" tabindex="-1">Lesson 1 · 定语从句与证据限定 <a class="header-anchor" href="#lesson-1-·-定语从句与证据限定" aria-label="Permalink to &quot;Lesson 1 · 定语从句与证据限定 {#lesson-1-·-定语从句与证据限定}&quot;">​</a></h2><ul><li>at large — 逃逸而未被抓住，常置于名词后</li><li>come to light — 信息被发现，主语通常是事实或证据</li></ul><p><strong>句型示范：</strong> The tracks that we found near the gate may belong to a large dog.</p><p>that we found near the gate 修饰 tracks，that 作 found 的宾语；may 表示不确定推测。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-001">进入本课</a></p><h2 id="lesson-2-·-过去进行时与突发事件" tabindex="-1">Lesson 2 · 过去进行时与突发事件 <a class="header-anchor" href="#lesson-2-·-过去进行时与突发事件" aria-label="Permalink to &quot;Lesson 2 · 过去进行时与突发事件 {#lesson-2-·-过去进行时与突发事件}&quot;">​</a></h2><ul><li>in the middle of — 在某活动或时段中间</li><li>go wrong — 出故障或出现问题</li></ul><p><strong>句型示范：</strong> I was checking the clock when a loose screw fell onto the floor.</p><p>was checking 提供背景，fell 引入一个短暂的新事件；when 连接两者。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-002">进入本课</a></p><h2 id="lesson-3-·-过去完成时的时间参照" tabindex="-1">Lesson 3 · 过去完成时的时间参照 <a class="header-anchor" href="#lesson-3-·-过去完成时的时间参照" aria-label="Permalink to &quot;Lesson 3 · 过去完成时的时间参照 {#lesson-3-·-过去完成时的时间参照}&quot;">​</a></h2><ul><li>date back to — 追溯到某时期，常用一般现在时</li><li>piece together — 拼合碎片或逐步理清信息</li></ul><p><strong>句型示范：</strong> By the time the team reached the chamber, water had damaged several paintings.</p><p>reached 是过去参照点；had damaged 把损坏放在到达之前；by the time 表示到那个时间为止。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-003">进入本课</a></p><h2 id="lesson-4-·-used-to-与过去习惯" tabindex="-1">Lesson 4 · used to 与过去习惯 <a class="header-anchor" href="#lesson-4-·-used-to-与过去习惯" aria-label="Permalink to &quot;Lesson 4 · used to 与过去习惯 {#lesson-4-·-used-to-与过去习惯}&quot;">​</a></h2><ul><li>earn a living — 谋生，后面可接 by doing</li><li>be proud of — 为某事或某人感到自豪</li></ul><p><strong>句型示范：</strong> Leo used to hide his work clothes, but now he talks openly about his job.</p><p>used to hide 表示已改变的习惯；but now 与前半句构成明确时间对比。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-004">进入本课</a></p><h2 id="lesson-5-·-间接疑问句的陈述语序" tabindex="-1">Lesson 5 · 间接疑问句的陈述语序 <a class="header-anchor" href="#lesson-5-·-间接疑问句的陈述语序" aria-label="Permalink to &quot;Lesson 5 · 间接疑问句的陈述语序 {#lesson-5-·-间接疑问句的陈述语序}&quot;">​</a></h2><ul><li>check with — 向某人核实</li><li>on record — 公开记录在案</li></ul><p><strong>句型示范：</strong> The editor asked how many households the survey had covered.</p><p>how many households 为 covered 的宾语，the survey 为主语；had covered 表示调查在询问之前已进行。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-005">进入本课</a></p><h2 id="lesson-6-·-一般过去时的被动语态" tabindex="-1">Lesson 6 · 一般过去时的被动语态 <a class="header-anchor" href="#lesson-6-·-一般过去时的被动语态" aria-label="Permalink to &quot;Lesson 6 · 一般过去时的被动语态 {#lesson-6-·-一般过去时的被动语态}&quot;">​</a></h2><ul><li>in broad daylight — 在光天化日之下</li><li>make off with — 偷走某物后逃离</li></ul><p><strong>句型示范：</strong> Two display cases were damaged before the alarm was raised.</p><p>were damaged 与 was raised 均为过去时被动；cases 为复数，alarm 为单数。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-006">进入本课</a></p><h2 id="lesson-7-·-可数与不可数名词" tabindex="-1">Lesson 7 · 可数与不可数名词 <a class="header-anchor" href="#lesson-7-·-可数与不可数名词" aria-label="Permalink to &quot;Lesson 7 · 可数与不可数名词 {#lesson-7-·-可数与不可数名词}&quot;">​</a></h2><ul><li>in pieces — 成为碎片或散开状态</li><li>send in — 将材料寄送或提交给有关机构</li></ul><p><strong>句型示范：</strong> Several fragments were missing, but most of the printed number was still visible.</p><p>several fragments 为复数；most of the printed number 指单个号码的部分，谓语用 was。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-007">进入本课</a></p><h2 id="lesson-8-·-地点介词与移动路径" tabindex="-1">Lesson 8 · 地点介词与移动路径 <a class="header-anchor" href="#lesson-8-·-地点介词与移动路径" aria-label="Permalink to &quot;Lesson 8 · 地点介词与移动路径 {#lesson-8-·-地点介词与移动路径}&quot;">​</a></h2><ul><li>on foot — 步行，通常不用 by foot</li><li>at the foot of — 在山或建筑物底部</li></ul><p><strong>句型示范：</strong> A narrow path runs through the forest and ends at the old gate.</p><p>through 描述穿过内部空间，at 把大门作为终点；runs 与 ends 共用单数主语 path。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-008">进入本课</a></p><h2 id="lesson-9-·-比较级与比较对象一致" tabindex="-1">Lesson 9 · 比较级与比较对象一致 <a class="header-anchor" href="#lesson-9-·-比较级与比较对象一致" aria-label="Permalink to &quot;Lesson 9 · 比较级与比较对象一致 {#lesson-9-·-比较级与比较对象一致}&quot;">​</a></h2><ul><li>land on — 落在某个表面上</li><li>compared with — 与某对象比较时</li></ul><p><strong>句型示范：</strong> The second ramp was slightly steeper than the first, so the cart moved faster.</p><p>slightly 修饰 steeper，than the first 省略 ramp；faster 在此修饰 moved。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-009">进入本课</a></p><h2 id="lesson-10-·-过去反事实条件句" tabindex="-1">Lesson 10 · 过去反事实条件句 <a class="header-anchor" href="#lesson-10-·-过去反事实条件句" aria-label="Permalink to &quot;Lesson 10 · 过去反事实条件句 {#lesson-10-·-过去反事实条件句}&quot;">​</a></h2><ul><li>on board — 在船或飞机上</li><li>in time — 来得及，在所需时间之前</li></ul><p><strong>句型示范：</strong> If the crew had received the warning earlier, they might have changed course.</p><p>had received 假设过去条件，might have changed 表示可能而非必然的不同结果。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-010">进入本课</a></p><h2 id="lesson-11-·-转述要求与否定命令" tabindex="-1">Lesson 11 · 转述要求与否定命令 <a class="header-anchor" href="#lesson-11-·-转述要求与否定命令" aria-label="Permalink to &quot;Lesson 11 · 转述要求与否定命令 {#lesson-11-·-转述要求与否定命令}&quot;">​</a></h2><ul><li>have nothing to declare — 没有需要申报的物品，须以实际规定为准</li><li>account for — 解释某事的原因或去向</li></ul><p><strong>句型示范：</strong> The officer asked me to place the sealed box on the counter.</p><p>asked 为谓语，me 为宾语，to place 为宾语补足语；执行 place 的人是 me。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-011">进入本课</a></p><h2 id="lesson-12-·-第二条件句的假设距离" tabindex="-1">Lesson 12 · 第二条件句的假设距离 <a class="header-anchor" href="#lesson-12-·-第二条件句的假设距离" aria-label="Permalink to &quot;Lesson 12 · 第二条件句的假设距离 {#lesson-12-·-第二条件句的假设距离}&quot;">​</a></h2><ul><li>do without — 没有某物也设法生活或完成任务</li><li>depend on — 依赖某资源或条件</li></ul><p><strong>句型示范：</strong> If I lived on a remote island, I would choose a reliable radio over a television.</p><p>lived 表假设而非实际过去；would choose 是设想的选择；over 表示优先于。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-012">进入本课</a></p><h2 id="lesson-13-·-强调句的焦点" tabindex="-1">Lesson 13 · 强调句的焦点 <a class="header-anchor" href="#lesson-13-·-强调句的焦点" aria-label="Permalink to &quot;Lesson 13 · 强调句的焦点 {#lesson-13-·-强调句的焦点}&quot;">​</a></h2><ul><li>turn out to be — 最后发现原来是</li><li>at first sight — 初看时，强调初步印象</li></ul><p><strong>句型示范：</strong> It was the gardener&#39;s voice that finally reassured the visitor.</p><p>It was ... that 强调主语 the gardener&#39;s voice；还原为 The gardener&#39;s voice finally reassured the visitor。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-013">进入本课</a></p><h2 id="lesson-14-·-although-与-despite" tabindex="-1">Lesson 14 · although 与 despite <a class="header-anchor" href="#lesson-14-·-although-与-despite" aria-label="Permalink to &quot;Lesson 14 · although 与 despite {#lesson-14-·-although-与-despite}&quot;">​</a></h2><ul><li>in spite of — 尽管，后接名词性成分</li><li>be known for — 因某特征而闻名</li></ul><p><strong>句型示范：</strong> Although the businessman funded a clinic, his illegal methods still harmed the community.</p><p>although 从句承认善举，主句保留对手段的评价；still 强化让步关系。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-014">进入本课</a></p><h2 id="lesson-15-·-数量修饰语与-worth" tabindex="-1">Lesson 15 · 数量修饰语与 worth <a class="header-anchor" href="#lesson-15-·-数量修饰语与-worth" aria-label="Permalink to &quot;Lesson 15 · 数量修饰语与 worth {#lesson-15-·-数量修饰语与-worth}&quot;">​</a></h2><ul><li>get stuck — 被卡住或陷入困境</li><li>at a cost of — 以某种金额或代价</li></ul><p><strong>句型示范：</strong> A two-minute repair saved a toy worth only three pounds.</p><p>two-minute 修饰 repair，minute 不用复数；worth only three pounds 后置修饰 toy。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-015">进入本课</a></p><h2 id="lesson-16-·-one、it-与名词替代" tabindex="-1">Lesson 16 · one、it 与名词替代 <a class="header-anchor" href="#lesson-16-·-one、it-与名词替代" aria-label="Permalink to &quot;Lesson 16 · one、it 与名词替代 {#lesson-16-·-one、it-与名词替代}&quot;">​</a></h2><ul><li>belong to — 属于，通常不用进行时</li><li>pick out — 从多个对象中认出或挑出</li></ul><p><strong>句型示范：</strong> Of the two lambs, the one with a dark ear belonged to our neighbour.</p><p>the one 替代 lamb，with a dark ear 限定具体是哪一只；belonged 的主语仍为单数。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-016">进入本课</a></p><h2 id="lesson-17-·-最高级的范围与倍数" tabindex="-1">Lesson 17 · 最高级的范围与倍数 <a class="header-anchor" href="#lesson-17-·-最高级的范围与倍数" aria-label="Permalink to &quot;Lesson 17 · 最高级的范围与倍数 {#lesson-17-·-最高级的范围与倍数}&quot;">​</a></h2><ul><li>at the time — 在当时，用于限定历史判断</li><li>as long as — 在长度比较中表示和……一样长，另有条件用法</li></ul><p><strong>句型示范：</strong> The new footbridge is twice as long as the wooden one it replaced.</p><p>twice as long as 表示明确倍数；one 替代 footbridge；it replaced 为省略宾语关系词的定语从句。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-017">进入本课</a></p><h2 id="lesson-18-·-感官动词后的补语" tabindex="-1">Lesson 18 · 感官动词后的补语 <a class="header-anchor" href="#lesson-18-·-感官动词后的补语" aria-label="Permalink to &quot;Lesson 18 · 感官动词后的补语 {#lesson-18-·-感官动词后的补语}&quot;">​</a></h2><ul><li>set in motion — 使开始运转</li><li>in response to — 作为对某刺激的反应</li></ul><p><strong>句型示范：</strong> We watched the metal rings rotating while a low tone filled the room.</p><p>watched 加宾语 the metal rings 和 rotating，呈现观看中的持续动作；while 连接同时背景。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-018">进入本课</a></p><h2 id="lesson-19-·-have-加宾语加过去分词" tabindex="-1">Lesson 19 · have 加宾语加过去分词 <a class="header-anchor" href="#lesson-19-·-have-加宾语加过去分词" aria-label="Permalink to &quot;Lesson 19 · have 加宾语加过去分词 {#lesson-19-·-have-加宾语加过去分词}&quot;">​</a></h2><ul><li>put up a notice — 张贴告示</li><li>get in touch with — 与某人取得联系</li></ul><p><strong>句型示范：</strong> After the gate broke, we had a new lock fitted to keep the dog safely inside.</p><p>had 为一般过去时，a new lock 是宾语，fitted 是过去分词补语；to keep 表目的。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-019">进入本课</a></p><h2 id="lesson-20-·-过去将来时与计划结果" tabindex="-1">Lesson 20 · 过去将来时与计划结果 <a class="header-anchor" href="#lesson-20-·-过去将来时与计划结果" aria-label="Permalink to &quot;Lesson 20 · 过去将来时与计划结果 {#lesson-20-·-过去将来时与计划结果}&quot;">​</a></h2><ul><li>take off — 飞机起飞，亦可指脱衣，需辨语境</li><li>set a record — 创造纪录</li></ul><p><strong>句型示范：</strong> The pilot believed that the lighter engine would extend the aircraft&#39;s range.</p><p>believed 建立过去视点；would extend 指相对于相信时刻尚未发生的预期。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-020">进入本课</a></p><h2 id="lesson-21-·-完成时不定式的先后关系" tabindex="-1">Lesson 21 · 完成时不定式的先后关系 <a class="header-anchor" href="#lesson-21-·-完成时不定式的先后关系" aria-label="Permalink to &quot;Lesson 21 · 完成时不定式的先后关系 {#lesson-21-·-完成时不定式的先后关系}&quot;">​</a></h2><ul><li>rise to fame — 成名</li><li>fall into debt — 陷入债务</li></ul><p><strong>句型示范：</strong> The retired athlete appears to have inspired a new generation of coaches.</p><p>appears 为现在判断，to have inspired 指此前发生并留下影响的行为。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-021">进入本课</a></p><h2 id="lesson-22-·-should-have-done-的过去评价" tabindex="-1">Lesson 22 · should have done 的过去评价 <a class="header-anchor" href="#lesson-22-·-should-have-done-的过去评价" aria-label="Permalink to &quot;Lesson 22 · should have done 的过去评价 {#lesson-22-·-should-have-done-的过去评价}&quot;">​</a></h2><ul><li>learn by heart — 熟记到能脱离文本复述</li><li>lose one&#39;s place — 忘记读到或说到哪里</li></ul><p><strong>句型示范：</strong> I missed my cue because I had not rehearsed; I should have checked the recording twice.</p><p>had not rehearsed 交代此前缺失的准备；should have checked 评价未完成的适当行动。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-022">进入本课</a></p><h2 id="lesson-23-·-prefer-与-would-rather" tabindex="-1">Lesson 23 · prefer 与 would rather <a class="header-anchor" href="#lesson-23-·-prefer-与-would-rather" aria-label="Permalink to &quot;Lesson 23 · prefer 与 would rather {#lesson-23-·-prefer-与-would-rather}&quot;">​</a></h2><ul><li>an acquired taste — 需要逐渐习惯才会欣赏的口味</li><li>appeal to — 对某人有吸引力</li></ul><p><strong>句型示范：</strong> I prefer tasting a small portion to rejecting an unfamiliar dish immediately.</p><p>tasting 与 rejecting 为平行动名词结构；to 是介词而非不定式标记。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-023">进入本课</a></p>',120)])])}const g=o(l,[["render",t]]);export{u as __pageData,g as default};
